import{_ as t,o as a,c as o,aj as i}from"./chunks/framework.C6uXqnaX.js";const f=JSON.parse('{"title":"Workspace and project file structure","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/configs/file-structure.md","filePath":"en/reference/configs/file-structure.md"}'),s={name:"en/reference/configs/file-structure.md"};function n(r,e,l,c,p,d){return a(),o("div",null,e[0]||(e[0]=[i(`<h1 id="workspace-and-project-file-structure" tabindex="-1">Workspace and project file structure <a class="header-anchor" href="#workspace-and-project-file-structure" aria-label="Permalink to &quot;Workspace and project file structure&quot;">​</a></h1><p>You develop applications in the context of an Angular workspace. A workspace contains the files for one or more projects. A project is the set of files that comprise an application or a shareable library.</p><p>The Angular CLI <code>ng new</code> command creates a workspace.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre></div><p>When you run this command, the CLI installs the necessary Angular npm packages and other dependencies in a new workspace, with a root-level application named <em>my-project</em>.</p><p>By default, <code>ng new</code> creates an initial skeleton application at the root level of the workspace. The skeleton is for a simple welcome application that is ready to run and easy to modify. The root-level application has the same name as the workspace, and the source files reside in the <code>src/</code> subfolder of the workspace.</p><p>This default behavior is suitable for a typical &quot;multi-repo&quot; development style where each application resides in its own workspace. Beginners and intermediate users are encouraged to use <code>ng new</code> to create a separate workspace for each application.</p><p>Angular also supports workspaces with <a href="#multiple-projects">multiple projects</a>. This type of development environment is suitable for advanced users who are developing shareable libraries, and for enterprises that use a &quot;monorepo&quot; development style, with a single repository and global configuration for all Angular projects.</p><p>To set up a monorepo workspace, you should skip creating the root application. See <a href="#multiple-projects">Setting up for a multi-project workspace</a> below.</p><h2 id="workspace-configuration-files" tabindex="-1">Workspace configuration files <a class="header-anchor" href="#workspace-configuration-files" aria-label="Permalink to &quot;Workspace configuration files&quot;">​</a></h2><p>All projects within a workspace share a <a href="/en/reference/configs/workspace-config">configuration</a>. The top level of the workspace contains workspace-wide configuration files, configuration files for the root-level application, and subfolders for the root-level application source and test files.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Workspace configuration files</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.editorconfig</code></td><td style="text-align:left;">Configuration for code editors. See <a href="https://editorconfig.org" target="_blank" rel="noreferrer">EditorConfig</a>.</td></tr><tr><td style="text-align:left;"><code>.gitignore</code></td><td style="text-align:left;">Specifies intentionally untracked files that <a href="https://git-scm.com" target="_blank" rel="noreferrer">Git</a> should ignore.</td></tr><tr><td style="text-align:left;"><code>README.md</code></td><td style="text-align:left;">Documentation for the workspace.</td></tr><tr><td style="text-align:left;"><code>angular.json</code></td><td style="text-align:left;">CLI configuration for all projects in the workspace, including configuration options for how to build, serve, and test each project. For details, see <a href="/en/reference/configs/workspace-config">Angular Workspace Configuration</a>.</td></tr><tr><td style="text-align:left;"><code>package.json</code></td><td style="text-align:left;">Configures <a href="/en/reference/configs/npm-packages">npm package dependencies</a> that are available to all projects in the workspace. See <a href="https://docs.npmjs.com/files/package.json" target="_blank" rel="noreferrer">npm documentation</a> for the specific format and contents of this file.</td></tr><tr><td style="text-align:left;"><code>package-lock.json</code></td><td style="text-align:left;">Provides version information for all packages installed into <code>node_modules</code> by the npm client. See <a href="https://docs.npmjs.com/files/package-lock.json" target="_blank" rel="noreferrer">npm documentation</a> for details.</td></tr><tr><td style="text-align:left;"><code>src/</code></td><td style="text-align:left;">Source files for the root-level application project.</td></tr><tr><td style="text-align:left;"><code>public/</code></td><td style="text-align:left;">Contains image and other asset files to be served as static files by the dev server and copied as-is when you build your application.</td></tr><tr><td style="text-align:left;"><code>node_modules/</code></td><td style="text-align:left;">Installed <a href="/en/reference/configs/npm-packages">npm packages</a> for the entire workspace. Workspace-wide <code>node_modules</code> dependencies are visible to all projects.</td></tr><tr><td style="text-align:left;"><code>tsconfig.json</code></td><td style="text-align:left;">The base <a href="https://www.typescriptlang.org" target="_blank" rel="noreferrer">TypeScript</a> configuration for projects in the workspace. All other configuration files inherit from this base file. For more information, see the <a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html#tsconfig-bases" target="_blank" rel="noreferrer">relevant TypeScript documentation</a>.</td></tr></tbody></table><h2 id="application-project-files" tabindex="-1">Application project files <a class="header-anchor" href="#application-project-files" aria-label="Permalink to &quot;Application project files&quot;">​</a></h2><p>By default, the CLI command <code>ng new my-app</code> creates a workspace folder named &quot;my-app&quot; and generates a new application skeleton in a <code>src/</code> folder at the top level of the workspace. A newly generated application contains source files for a root component and template.</p><p>When the workspace file structure is in place, you can use the <code>ng generate</code> command on the command line to add functionality and data to the application. This initial root-level application is the <em>default app</em> for CLI commands (unless you change the default after creating <a href="#multiple-projects">additional apps</a>).</p><p>For a single-application workspace, the <code>src</code> subfolder of the workspace contains the source files (application logic, data, and assets) for the root application. For a multi-project workspace, additional projects in the <code>projects</code> folder contain a <code>project-name/src/</code> subfolder with the same structure.</p><h3 id="application-source-files" tabindex="-1">Application source files <a class="header-anchor" href="#application-source-files" aria-label="Permalink to &quot;Application source files&quot;">​</a></h3><p>Files at the top level of <code>src/</code> support running your application. Subfolders contain the application source and application-specific configuration.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Application support files</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>app/</code></td><td style="text-align:left;">Contains the component files in which your application logic and data are defined. See details below.</td></tr><tr><td style="text-align:left;"><code>index.html</code></td><td style="text-align:left;">The main HTML page that is served when someone visits your site. The CLI automatically adds all JavaScript and CSS files when building your app, so you typically don&#39;t need to add any <code>&lt;script&gt;</code> or<code>&lt;link&gt;</code> tags here manually.</td></tr><tr><td style="text-align:left;"><code>main.ts</code></td><td style="text-align:left;">The main entry point for your application.</td></tr><tr><td style="text-align:left;"><code>styles.css</code></td><td style="text-align:left;">Global CSS styles applied to the entire application.</td></tr></tbody></table><p>Inside the <code>src</code> folder, the <code>app</code> folder contains your project&#39;s logic and data. Angular components, templates, and styles go here.</p><table tabindex="0"><thead><tr><th style="text-align:left;"><code>src/app/</code> files</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>app.config.ts</code></td><td style="text-align:left;">Defines the application configuration that tells Angular how to assemble the application. As you add more providers to the app, they should be declared here.<br><br><em>Only generated when using the <code>--standalone</code> option.</em></td></tr><tr><td style="text-align:left;"><code>app.ts</code></td><td style="text-align:left;">Defines the application&#39;s root component, named <code>App</code>. The view associated with this root component becomes the root of the view hierarchy as you add components and services to your application.</td></tr><tr><td style="text-align:left;"><code>app.html</code></td><td style="text-align:left;">Defines the HTML template associated with <code>App</code>.</td></tr><tr><td style="text-align:left;"><code>app.css</code></td><td style="text-align:left;">Defines the CSS stylesheet for <code>App</code>.</td></tr><tr><td style="text-align:left;"><code>app.spec.ts</code></td><td style="text-align:left;">Defines a unit test for <code>App</code>.</td></tr><tr><td style="text-align:left;"><code>app-module.ts</code></td><td style="text-align:left;">Defines the root module, named <code>AppModule</code>, that tells Angular how to assemble the application. Initially declares only the <code>App</code> component. As you add more components to the app, they must be declared here.<br><br><em>Only generated when using the <code>--standalone false</code> option.</em></td></tr><tr><td style="text-align:left;"><code>app.routes.ts</code></td><td style="text-align:left;">Defines the application&#39;s routing configuration.</td></tr></tbody></table><h3 id="application-configuration-files" tabindex="-1">Application configuration files <a class="header-anchor" href="#application-configuration-files" aria-label="Permalink to &quot;Application configuration files&quot;">​</a></h3><p>Application-specific configuration files for the root application reside at the workspace root level. For a multi-project workspace, project-specific configuration files are in the project root, under <code>projects/project-name/</code>.</p><p>Project-specific <a href="https://www.typescriptlang.org" target="_blank" rel="noreferrer">TypeScript</a> configuration files inherit from the workspace-wide <code>tsconfig.json</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Application-specific configuration files</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>tsconfig.app.json</code></td><td style="text-align:left;">Application-specific <a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">TypeScript configuration</a>, including <a href="/en/reference/configs/angular-compiler-options">Angular compiler options</a>.</td></tr><tr><td style="text-align:left;"><code>tsconfig.spec.json</code></td><td style="text-align:left;"><a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">TypeScript configuration</a> for application tests.</td></tr></tbody></table><h2 id="multiple-projects" tabindex="-1">Multiple projects <a class="header-anchor" href="#multiple-projects" aria-label="Permalink to &quot;Multiple projects&quot;">​</a></h2><p>A multi-project workspace is suitable for an organization that uses a single repository and global configuration for multiple Angular projects (the &quot;monorepo&quot; model). A multi-project workspace also supports library development.</p><h3 id="setting-up-for-a-multi-project-workspace" tabindex="-1">Setting up for a multi-project workspace <a class="header-anchor" href="#setting-up-for-a-multi-project-workspace" aria-label="Permalink to &quot;Setting up for a multi-project workspace&quot;">​</a></h3><p>If you intend to have multiple projects in a workspace, you can skip the initial application generation when you create the workspace, and give the workspace a unique name. The following command creates a workspace with all of the workspace-wide configuration files, but no root-level application.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-create-application</span></span></code></pre></div><p>You can then generate applications and libraries with names that are unique within the workspace.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-lib</span></span></code></pre></div><h3 id="multiple-project-file-structure" tabindex="-1">Multiple project file structure <a class="header-anchor" href="#multiple-project-file-structure" aria-label="Permalink to &quot;Multiple project file structure&quot;">​</a></h3><p>The first explicitly generated application goes into the <code>projects</code> folder along with all other projects in the workspace. Newly generated libraries are also added under <code>projects</code>. When you create projects this way, the file structure of the workspace is entirely consistent with the structure of the <a href="/en/reference/configs/workspace-config">workspace configuration file</a>, <code>angular.json</code>.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my-workspace/</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├── … (workspace-wide configuration files)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">└── projects/ (applications and libraries)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├── my-app/ (an explicitly generated application)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">│ └── … (application-specific code and configuration)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">└── my-lib/ (a generated library)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">└── … (library-specific code and configuration)</span></span></code></pre></div><h2 id="library-project-files" tabindex="-1">Library project files <a class="header-anchor" href="#library-project-files" aria-label="Permalink to &quot;Library project files&quot;">​</a></h2><p>When you generate a library using the CLI (with a command such as <code>ng generate library my-lib</code>), the generated files go into the <code>projects/</code> folder of the workspace. For more information about creating your own libraries, see <a href="/en/tools/libraries/creating-libraries">Creating Libraries</a>.</p><p>Unlike an application, a library has its own <code>package.json</code> configuration file.</p><p>Under the <code>projects/</code> folder, the <code>my-lib</code> folder contains your library code.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Library source files</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/lib</code></td><td style="text-align:left;">Contains your library project&#39;s logic and data. Like an application project, a library project can contain components, services, modules, directives, and pipes.</td></tr><tr><td style="text-align:left;"><code>src/public-api.ts</code></td><td style="text-align:left;">Specifies all files that are exported from your library&#39;s primary entry point.</td></tr><tr><td style="text-align:left;"><code>package.json</code></td><td style="text-align:left;">Configures <a href="/en/reference/configs/npm-packages">npm package dependencies</a> and entry points (<code>exports</code>) for this library.</td></tr><tr><td style="text-align:left;"><code>tsconfig.lib.json</code></td><td style="text-align:left;">Library-specific <a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">TypeScript Configuration</a>, including <a href="/en/reference/configs/angular-compiler-options">Angular compiler options</a>.</td></tr><tr><td style="text-align:left;"><code>tsconfig.spec.json</code></td><td style="text-align:left;"><a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">TypeScript Configuration</a> for the library&#39;s unit tests.</td></tr></tbody></table>`,40)]))}const g=t(s,[["render",n]]);export{f as __pageData,g as default};
